import React from 'react'; import { BrowserRouter as Router, Routes, Route } from 'react-router-dom'; import './styles/globals.css';
import Login from './pages/Login'; import Register from './pages/Register'; import ChooseRole from './pages/ChooseRole'; import DashboardCustomer from './pages/DashboardCustomer'; import DashboardWorker from './pages/DashboardWorker'; import AIPlanner from './pages/AIPlanner'; import OrderDetail from './pages/OrderDetail'; import Payment from './pages/Payment'; import Uikit from './pages/Uikit'; import RegisterWorker from './pages/RegisterWorker'; import SkillAssessment from './pages/SkillAssessment'; import TaskDetail from './pages/TaskDetail'; import WorkSpace from './pages/WorkSpace'; import Inbox from './pages/Inbox'; import ChatDetail from './pages/ChatDetail'; import Wallet from './pages/Wallet'; import PaymentMethod from './pages/PaymentMethod'; import Rating from './pages/Rating'; import CancelOrder from './pages/CancelOrder'; import DisputeCenter from './pages/DisputeCenter'; import WorkerProfile from './pages/WorkerProfile'; import OrderStatus from './pages/OrderStatus';
function App() { return (<Router><Routes><Route path="/" element={<Login />} /><Route path="/register" element={<Register />} /><Route path="/choose-role" element={<ChooseRole />} /><Route path="/dashboard-customer" element={<DashboardCustomer />} /><Route path="/dashboard-worker" element={<DashboardWorker />} /><Route path="/ai-planner" element={<AIPlanner />} /><Route path="/order-detail" element={<OrderDetail />} /><Route path="/payment" element={<Payment />} /><Route path="/uikit" element={<Uikit />} /><Route path="/register-worker" element={<RegisterWorker />} /><Route path="/skill-assessment" element={<SkillAssessment />} /><Route path="/task-detail" element={<TaskDetail />} /><Route path="/workspace" element={<WorkSpace />} /><Route path="/inbox" element={<Inbox />} /><Route path="/chat-detail" element={<ChatDetail />} /><Route path="/wallet" element={<Wallet />} /><Route path="/payment-method" element={<PaymentMethod />} /><Route path="/rating" element={<Rating />} /><Route path="/cancel-order" element={<CancelOrder />} /><Route path="/dispute-center" element={<DisputeCenter />} /><Route path="/worker-profile" element={<WorkerProfile />} /><Route path="/order-status" element={<OrderStatus />} /></Routes></Router>); }
export default App;
